"@echo off`r`nwhere pwsh.exe >nul 2>&1`r`nif %errorlevel%==0 (pwsh.exe -NoProfile -ExecutionPolicy Bypass -File `"%ProgramData%\System8\Packages\m365-migration-estimator\migration-estimator.ps1`" %*) else (powershell.exe -NoProfile -ExecutionPolicy Bypass -File `"%ProgramData%\System8\Packages\m365-migration-estimator\migration-estimator.ps1`" %*)"|Set-Content (Join-Path $bin 's8migrate.cmd') -Encoding ASCII;Write-Host 'Installed command: s8migrate' -ForegroundColor Green
